        for c in range(w):
            color = grid[r][c]
            if color == bg or seen[r][c]:
                continue

            stack = [(r, c)]
            seen[r][c] = True
            component = []
            while stack:
                y, x = stack.pop()
                component.append((y, x))
                for ny, nx in ((y-1, x), (y+1, x), (y, x-1), (y, x+1)):
                    if (0 <= ny < h and 0 <= nx < w and not seen[ny][nx]
                            and grid[ny][nx] == color):
